"""Recorded survivor movements for offline labels only."""
import copy
import json
from functools import lru_cache
from brain.oracle import load_survivors

@lru_cache(maxsize=8)
def events(recording):
    path=recording/'rescues.jsonl'
    return tuple(json.loads(line) for line in path.read_text().splitlines()) if path.exists() else ()

def survivors_at(recording,t):
    survivors=copy.deepcopy(load_survivors(recording))
    carrying=set()
    for event in events(recording):
        if event['t']>t:
            continue
        survivor=next((s for s in survivors if event['person'].startswith('Survivor_'+s['id']+'_')),None)
        if survivor is None:
            raise ValueError('Unknown moved survivor')
        if event['event']=='gripped':
            carrying.add(survivor['id'])
        elif event['event']=='released':
            carrying.discard(survivor['id'])
            survivor['position_house']=[event['x'],0.,event['z']]
    return survivors,sorted(carrying)
